import os, subprocess, sys
from part6_designs import *

check_only = "--check" in sys.argv

def done(path):
    if not os.path.exists(path):
        return False
    return any(l.startswith("sim_IPC") for l in open(path))

print("Default design cost = %.2f (the statement says 86)\n" % cost(DESIGNS[0]))
print("%-24s%8s  status" % ("design", "cost"))
todo, lines = [], ["#!/bin/bash",
                   "# generated by scripts/run_P6.py: every Part 6 command",
                   "cd " + INPUT + " || exit 1"]
for dz in DESIGNS:
    pr = problems(dz)
    print("%-24s%8.2f  %s" % (dz["name"], cost(dz), "OK" if not pr else "INVALID: " + "; ".join(pr)))
    if pr:
        continue
    for b in BENCHES:
        out = "%s/%s_P6_%s.txt" % (RES, b, dz["name"])
        if b == "compress95":
            tail, stdin = ["../Programs/compress95.ss"], "compress95.in"
            suffix = " < compress95.in > /dev/null"
        else:
            tail, stdin = ["../Programs/cc1.ss", "-O", "1stmt.i"], None
            suffix = " > /dev/null"
        args = [SIM] + options(dz) + ["-redir:sim", out] + tail
        lines.append("env -i " + " ".join(args) + suffix)
        todo.append((dz["name"], b, out, args, stdin))

open(ROOT + "/scripts/P6_commands.sh", "w").write("\n".join(lines) + "\n")
print("\nWrote scripts/P6_commands.sh (all exact commands)")
if check_only:
    sys.exit(0)

for name, b, out, args, stdin in todo:
    if done(out):
        continue
    print("running", b, name, flush=True)
    fin = open(os.path.join(INPUT, stdin)) if stdin else None
    r = subprocess.run(args, cwd=INPUT, env={}, stdin=fin,
                       stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True)
    if fin:
        fin.close()
    if not done(out):
        print("  FAILED:", b, name, (r.stderr or "")[-300:])
print("all done")